//! #515: lmfd's LPP on the generated codec, checked against the pre-migration
//! hand-written code ([`crate::lpp_oracle`]).
//!
//! Builders: the generated bytes, read by the hand-written decoder, are the value
//! the old builder produced. Byte identity is asserted only where no extension
//! addition is present; with additions the presence bitmap is as long as the
//! additions the encoder's schema knows (X.691 §19.7), and the Rel-19 schema knows
//! more than the hand-written encoder — both conformant.
//!
//! Decoders: every hand-written-encoded report in the matrix adapts to the same
//! `CellMeasurement`s through the generated decoder as through the old adapter.

use crate::codec_glue::{self, LppMethod, UeLppCapability};
use crate::lpp_oracle as old;
use bitvec::prelude::*;
use nextgcore_asn1c::lpp::ecid::{
    EcidProvideLocationInformation, EcidSignalMeasurementInformation, MeasuredResultsElement,
    ProvideLocationInformation, ProvideLocationInformationR9,
};
use nextgcore_asn1c::lpp::message::{LppMessage, LppMessageBody, MessageBodyC1};
use nextgcore_asn1c::lpp::nr_dl_tdoa::{
    DlPrsIdInfo, NrDlTdoaMeasElement, NrDlTdoaMeasList, NrDlTdoaProvideLocationInformation,
    NrDlTdoaSignalMeasurementInformation, NrRstd, NrSlot, NrTimeStamp, NrTimingQuality,
};
use nextgcore_asn1c::lpp::nr_multi_rtt::{
    NrMultiRttMeasElement, NrMultiRttMeasList, NrMultiRttProvideLocationInformation,
    NrMultiRttSignalMeasurementInformation,
};
use nextgcore_asn1c::lpp::types::{Initiator, LppTransactionId, TransactionNumber};
use nextgcore_lpp_gen::generated as lpp;

fn hand(bytes: &[u8]) -> LppMessage {
    LppMessage::decode(bytes).expect("hand-written decode")
}

fn to_gen(m: &LppMessage) -> lpp::LPP_Message {
    codec_glue::decode_lpp(&m.encode().expect("hand encode")).expect("generated decode")
}

#[test]
fn ecid_request_is_byte_identical_to_the_old_builder() {
    for txn in [0u8, 1, 7, 127, 128, 255] {
        let new = codec_glue::build_lpp_ecid_request(txn).unwrap();
        let old = old::build_lpp_ecid_request(txn).unwrap();
        assert_eq!(new, old, "txn {txn}");
        let via_method = codec_glue::build_lpp_request(LppMethod::Ecid, txn).unwrap();
        assert_eq!(via_method, old, "LppMethod::Ecid txn {txn}");
    }
}

#[test]
fn nr_requests_carry_the_old_builders_value() {
    for method in [LppMethod::MultiRtt, LppMethod::DlTdoa] {
        for txn in [0u8, 1, 127, 255] {
            let new = codec_glue::build_lpp_request(method, txn).unwrap();
            let old = old::build_lpp_request(method, txn).unwrap();
            assert_eq!(hand(&new), hand(&old), "{method:?} txn {txn}");
        }
    }
}

#[test]
fn provide_assistance_data_matches_the_old_builder() {
    for (lat, lon, unc) in [
        (0.0, 0.0, 0.0),
        (51.477_8, -0.001_5, 25.0),
        (-33.856_8, 151.215_3, 1_800.0),
        (90.0, 180.0, 1.0e6),
        (-90.0, -180.0, 3.0),
    ] {
        for txn in [0u8, 9, 255] {
            let new = codec_glue::build_lpp_provide_assistance_data(txn, lat, lon, unc).unwrap();
            let old = old::build_lpp_provide_assistance_data(txn, lat, lon, unc).unwrap();
            // No extension addition is present anywhere in this message.
            assert_eq!(new, old, "lat {lat} lon {lon} unc {unc} txn {txn}");
        }
    }
}

fn envelope(txn: u8, body: ProvideLocationInformationR9) -> LppMessage {
    LppMessage {
        transaction_id: Some(LppTransactionId {
            initiator: Initiator::TargetDevice,
            transaction_number: TransactionNumber(txn),
        }),
        end_transaction: true,
        sequence_number: None,
        acknowledgement: None,
        message_body: Some(LppMessageBody::C1(
            MessageBodyC1::ProvideLocationInformation(ProvideLocationInformation { ies: body }),
        )),
    }
}

fn empty_r9() -> ProvideLocationInformationR9 {
    ProvideLocationInformationR9 {
        ecid: None,
        nr_multi_rtt: None,
        nr_dl_tdoa: None,
        sidelink_ranging: None,
    }
}

fn element(
    pci: u16,
    arfcn: u32,
    rsrp: Option<u8>,
    rsrq: Option<u8>,
    ta: Option<u16>,
) -> MeasuredResultsElement {
    MeasuredResultsElement {
        phys_cell_id: pci,
        arfcn_eutra: arfcn,
        system_frame_number: None,
        rsrp_result: rsrp,
        rsrq_result: rsrq,
        ue_rx_tx_time_diff: ta,
    }
}

fn ecid_reports() -> Vec<LppMessage> {
    let mut out = Vec::new();
    let elems = [
        element(0, 0, None, None, None),
        element(503, 65_535, Some(97), Some(34), Some(4_095)),
        element(42, 1_850, Some(0), Some(0), Some(0)),
        element(7, 300, Some(50), None, Some(1_200)),
    ];
    for primary in [None, Some(elems[1].clone())] {
        for n in 1..=4usize {
            out.push(envelope(
                n as u8,
                ProvideLocationInformationR9 {
                    ecid: Some(EcidProvideLocationInformation {
                        signal_measurement_information: Some(EcidSignalMeasurementInformation {
                            primary_cell_measured_results: primary.clone(),
                            measured_results_list: elems[..n].to_vec(),
                        }),
                        ecid_error: None,
                    }),
                    ..empty_r9()
                },
            ));
        }
    }
    out
}

fn timestamp() -> NrTimeStamp {
    NrTimeStamp {
        dl_prs_id: 5,
        nr_phys_cell_id: Some(123),
        nr_arfcn: None,
        nr_sfn: 700,
        nr_slot: NrSlot::Scs30(11),
    }
}

fn quality() -> NrTimingQuality {
    NrTimingQuality {
        timing_quality_value: 12,
        timing_quality_resolution: 2,
    }
}

/// Every k-arm at its extremes and its midpoint.
fn time_values() -> Vec<NrRstd> {
    let max = [1_970_049u32, 985_025, 492_513, 246_257, 123_129, 61_565];
    let mut out = Vec::new();
    for (k, m) in max.iter().enumerate() {
        for v in [0, m / 2, *m] {
            out.push(match k {
                0 => NrRstd::K0(v),
                1 => NrRstd::K1(v),
                2 => NrRstd::K2(v),
                3 => NrRstd::K3(v),
                4 => NrRstd::K4(v),
                _ => NrRstd::K5(v),
            });
        }
    }
    out
}

fn multi_rtt_reports() -> Vec<LppMessage> {
    let mut out = Vec::new();
    for (i, t) in time_values().into_iter().enumerate() {
        let items: Vec<_> = (0..1 + i % 4)
            .map(|j| NrMultiRttMeasElement {
                dl_prs_id: (i * 7 + j) as u8,
                nr_phys_cell_id: if j % 2 == 0 {
                    Some((i * 37 % 1008) as u16)
                } else {
                    None
                },
                nr_arfcn: Some(640_000),
                nr_ue_rx_tx_time_diff: t,
                nr_time_stamp: timestamp(),
                nr_timing_quality: quality(),
                nr_dl_prs_rsrp_result: if j == 1 {
                    None
                } else {
                    Some((i * 9 % 127) as u8)
                },
            })
            .collect();
        out.push(envelope(
            i as u8,
            ProvideLocationInformationR9 {
                nr_multi_rtt: Some(NrMultiRttProvideLocationInformation {
                    signal_measurement_information: Some(NrMultiRttSignalMeasurementInformation {
                        meas_list: NrMultiRttMeasList { items },
                    }),
                }),
                ..empty_r9()
            },
        ));
    }
    out
}

fn dl_tdoa_reports() -> Vec<LppMessage> {
    let mut out = Vec::new();
    for (i, t) in time_values().into_iter().enumerate() {
        let items: Vec<_> = (0..1 + i % 4)
            .map(|j| NrDlTdoaMeasElement {
                dl_prs_id: (i * 3 + j) as u8,
                nr_phys_cell_id: if j % 2 == 1 {
                    Some(((i + j) * 53 % 1008) as u16)
                } else {
                    None
                },
                nr_arfcn: None,
                nr_time_stamp: timestamp(),
                nr_rstd: t,
                nr_timing_quality: quality(),
                nr_dl_prs_rsrp_result: if j == 0 {
                    Some((i * 5 % 127) as u8)
                } else {
                    None
                },
            })
            .collect();
        out.push(envelope(
            200u8.wrapping_add(i as u8),
            ProvideLocationInformationR9 {
                nr_dl_tdoa: Some(NrDlTdoaProvideLocationInformation {
                    signal_measurement_information: Some(NrDlTdoaSignalMeasurementInformation {
                        dl_prs_reference_info: DlPrsIdInfo {
                            dl_prs_id: (i % 256) as u8,
                        },
                        meas_list: NrDlTdoaMeasList { items },
                    }),
                }),
                ..empty_r9()
            },
        ));
    }
    out
}

#[test]
fn every_report_adapts_as_the_old_adapters_did() {
    let mut cases = 0;
    for msg in ecid_reports()
        .into_iter()
        .chain(multi_rtt_reports())
        .chain(dl_tdoa_reports())
    {
        let g = to_gen(&msg);
        assert_eq!(
            format!("{:?}", codec_glue::lpp_ecid_provide_to_measurements(&g)),
            format!("{:?}", old::lpp_ecid_provide_to_measurements(&msg)),
            "E-CID {msg:?}"
        );
        assert_eq!(
            format!(
                "{:?}",
                codec_glue::lpp_multi_rtt_provide_to_measurements(&g)
            ),
            format!("{:?}", old::lpp_multi_rtt_provide_to_measurements(&msg)),
            "Multi-RTT {msg:?}"
        );
        assert_eq!(
            format!("{:?}", codec_glue::lpp_dl_tdoa_provide_to_measurements(&g)),
            format!("{:?}", old::lpp_dl_tdoa_provide_to_measurements(&msg)),
            "DL-TDOA {msg:?}"
        );
        let bytes = msg.encode().unwrap();
        let (id, _) = codec_glue::decode_lpp_provide_report(&bytes).unwrap();
        assert_eq!(
            id,
            u64::from(msg.transaction_id.as_ref().unwrap().transaction_number.0)
        );
        cases += 1;
    }
    assert_eq!(cases, 8 + 18 + 18);
}

/// The Rel-18 finer-granularity arms (kMinus6..kMinus1) no hand-written codec could
/// carry: `v × 2^k × T_c` with a negative k, and the RSTD keeps its midpoint.
#[test]
fn rel18_fine_granularity_arms_convert() {
    use codec_glue::{nrrstd_to_ns, nrrstd_to_signed_ns, TimeReport};
    let tc = 1_000_000_000.0 / (480_000.0 * 4_096.0);
    // kMinus6: the midpoint is 985024 × 64.
    assert_eq!(
        nrrstd_to_signed_ns(TimeReport {
            v: 985_024 * 64,
            k: -6
        }),
        0.0
    );
    assert!(
        (nrrstd_to_signed_ns(TimeReport {
            v: 985_024 * 64 + 64,
            k: -6
        }) - tc)
            .abs()
            < 1e-9
    );
    // kMinus1: two steps of 2^-1 make one T_c.
    assert_eq!(
        nrrstd_to_ns(TimeReport { v: 2_000, k: -1 }),
        (1_000.0 * tc) as u64
    );
}

#[test]
fn capability_classification_reads_the_generated_report() {
    use nextgcore_asn1c::lpp::capabilities::{
        CommonIEsProvideCapabilities, EcidProvideCapabilities, ProvideCapabilities,
        ProvideCapabilitiesR9,
    };
    let caps = |ecid: bool| {
        let msg = LppMessage {
            transaction_id: Some(LppTransactionId {
                initiator: Initiator::TargetDevice,
                transaction_number: TransactionNumber(1),
            }),
            end_transaction: true,
            sequence_number: None,
            acknowledgement: None,
            message_body: Some(LppMessageBody::C1(MessageBodyC1::ProvideCapabilities(
                ProvideCapabilities {
                    ies: ProvideCapabilitiesR9 {
                        common: Some(CommonIEsProvideCapabilities {}),
                        ecid: ecid.then(|| EcidProvideCapabilities {
                            ecid_meas_supported: bits(&[true, true, false]),
                        }),
                    },
                },
            ))),
        };
        match to_gen(&msg).lpp_message_body {
            Some(lpp::LPP_MessageBody::C1(lpp::LPP_MessageBody_c1::ProvideCapabilities(p))) => p,
            other => panic!("not ProvideCapabilities: {other:?}"),
        }
    };
    assert_eq!(
        codec_glue::classify_ue_capability(&caps(true)),
        UeLppCapability::EcidOnly
    );
    assert_eq!(
        codec_glue::classify_ue_capability(&caps(false)),
        UeLppCapability::Unknown
    );
}

fn bits(v: &[bool]) -> BitVec<u8, Msb0> {
    v.iter().copied().collect()
}

/// `build_lpp_ecid_request(0)` derived by hand from X.691 (UPER, TS 37.355):
///
/// | bits | field |
/// |------|-------|
/// | `1001` | LPP-Message optional bitmap: transactionID, ¬sequenceNumber, ¬acknowledgement, lpp-MessageBody |
/// | `0 0 0` | LPP-TransactionID ext bit; Initiator ext bit, value locationServer (1 bit) |
/// | `00000000` | transactionNumber 0, INTEGER(0..255) |
/// | `0` | endTransaction FALSE |
/// | `0 0100` | lpp-MessageBody c1; c1 index 4 = requestLocationInformation (4 bits) |
/// | `0 00` | criticalExtensions c1; requestLocationInformation-r9 (2 bits) |
/// | `0 00010` | r9-IEs ext bit; optional bitmap: only ecid-RequestLocationInformation |
/// | `0 001 11` | ECID ext bit; BIT STRING SIZE(1..8) length 2 as 3 bits; rsrpReq, rsrqReq |
///
/// 36 bits, padded: `90 00 20 08 70`.
#[test]
fn ecid_request_matches_x691() {
    assert_eq!(
        codec_glue::build_lpp_ecid_request(0).unwrap(),
        vec![0x90, 0x00, 0x20, 0x08, 0x70]
    );
}
